document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("btnMarkAllRead"),t=document.querySelectorAll(".notification-item"),n=document.querySelectorAll(".pref-item input");e&&e.addEventListener("click",function(){t.forEach(e=>{e.classList.remove("unread")}),showToast("All notifications marked as read","success")}),t.forEach(e=>{e.addEventListener("click",function(){this.classList.toggle("unread")});const t=e.querySelector(".btn-close");t&&t.addEventListener("click",function(t){t.stopPropagation(),e.style.transition="opacity 300ms ease-out",e.style.opacity="0",setTimeout(()=>{e.remove(),showToast("Notification dismissed","info")},300)})}),n.forEach(e=>{e.addEventListener("change",function(){const e=this.parentElement.querySelector("span").textContent,t=this.checked?"enabled":"disabled";showToast(`${e} ${t}`,"success")})})});